// Parse request and validate
const query = $input.item.json.query || {};
const action = query.action || 'get_lesson';
const studentId = parseInt(query.studentId) || 999;
const lessonId = parseInt(query.lessonId);
const topicId = parseInt(query.topicId);
const completionPercentage = parseInt(query.completionPercentage) || 100;
const confidenceRating = parseInt(query.confidenceRating);
const timeSpent = parseInt(query.timeSpent) || 0;

// Validate required fields based on action
if (action === 'get_lesson' && !lessonId && !topicId) {
  return {
    json: {
      error: true,
      message: 'Either lessonId or topicId is required',
      action
    }
  };
}

if (action === 'mark_complete' && !lessonId) {
  return {
    json: {
      error: true,
      message: 'lessonId is required for mark_complete action',
      action
    }
  };
}

// Sanitize inputs
const sanitize = (str, maxLength = 500) => {
  if (typeof str !== 'string') return '';
  return str.slice(0, maxLength).trim();
};

const notes = sanitize(query.notes || '', 1000);

return {
  json: {
    action,
    studentId,
    lessonId: lessonId || null,
    topicId: topicId || null,
    completionPercentage,
    confidenceRating: confidenceRating || null,
    timeSpent,
    notes,
    timestamp: new Date().toISOString()
  }
};

// Build lesson response
const lesson = $input.first().json;

if (!lesson || !lesson.lesson_id) {
  return {
    json: {
      success: false,
      error: 'Lesson not found',
      lessonId: $('Parse Request').item.json.lessonId
    }
  };
}

// Parse content blocks if string
let contentBlocks = lesson.content_blocks;
if (typeof contentBlocks === 'string') {
  try {
    contentBlocks = JSON.parse(contentBlocks);
  } catch (e) {
    contentBlocks = [];
  }
}

return {
  json: {
    success: true,
    lesson: {
      id: lesson.lesson_id,
      title: lesson.lesson_title,
      type: lesson.lesson_type,
      number: lesson.lesson_number,
      contentBlocks: contentBlocks || [],
      learningObjectives: lesson.learning_objectives || [],
      successCriteria: lesson.success_criteria || [],
      estimatedMinutes: lesson.estimated_minutes,
      difficultyRating: lesson.difficulty_rating,
      markSchemeNotes: lesson.mark_scheme_notes,
      examTips: lesson.exam_tips || [],
      commonMistakes: lesson.common_mistakes || [],
      topic: {
        id: lesson.topic_id,
        name: lesson.topic_name
      },
      subject: {
        id: lesson.subject_id,
        name: lesson.subject_name
      }
    },
    progress: {
      status: lesson.progress_status || 'not_started',
      completionPercentage: lesson.completion_percentage || 0,
      confidenceRating: lesson.confidence_rating || null,
      timeSpentMinutes: lesson.time_spent_minutes || 0,
      notes: lesson.student_notes || '',
      bookmarked: lesson.bookmarked || false,
      lastAccessedAt: lesson.last_accessed_at
    },
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

// Build lessons list response
const lessons = $input.all().map(item => item.json);
const request = $('Parse Request').item.json;

return {
  json: {
    success: true,
    topicId: request.topicId,
    lessons: lessons.map(l => ({
      id: l.lesson_id,
      title: l.lesson_title,
      type: l.lesson_type,
      number: l.lesson_number,
      estimatedMinutes: l.estimated_minutes,
      difficultyRating: l.difficulty_rating,
      progress: {
        status: l.progress_status || 'not_started',
        completionPercentage: l.completion_percentage || 0,
        confidenceRating: l.confidence_rating || null
      }
    })),
    meta: {
      totalLessons: lessons.length,
      timestamp: new Date().toISOString()
    }
  }
};

// Build completion response
const progress = $input.first().json;
const request = $('Parse Request').item.json;

return {
  json: {
    success: true,
    message: request.completionPercentage >= 100 ? 'Lesson completed!' : 'Progress saved',
    progress: {
      lessonId: progress.lesson_id,
      status: progress.status,
      completionPercentage: progress.completion_percentage,
      confidenceRating: progress.confidence_rating,
      timeSpentMinutes: progress.time_spent_minutes
    },
    student: {
      xpPoints: progress.xp_points,
      currentLevel: progress.current_level,
      totalLessonsCompleted: progress.total_lessons_completed,
      xpGained: request.completionPercentage >= 100 ? 20 : 5
    },
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

// Handle unknown action
const request = $input.item.json;

return {
  json: {
    success: false,
    error: 'Unknown action',
    action: request.action,
    validActions: ['get_lesson', 'get_lessons_by_topic', 'mark_complete']
  }
};

